MOD = 10**9 + 7

def count_similar_permutations(n, a):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            if dp[i - 1][j] > 0:
                mex = 0
                while mex in a[i - 1:j] or mex == j:
                    mex += 1
                dp[i][mex] = (dp[i][mex] + dp[i - 1][j]) % MOD
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    return sum(dp[n]) % MOD

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        results.append(count_similar_permutations(n, a))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
